<template><section><h2 class="text-2xl font-bold mb-6">Chi tiết đơn hàng</h2><p v-if="error" class="text-error">{{error}}</p><p v-else-if="!order" class="text-gray-400">Đang tải…</p><div v-else><div class="grid sm:grid-cols-2 gap-4"><div v-for="(value,key) in fields" :key="key" class="rounded bg-white/5 p-4"><p class="text-sm text-gray-400">{{key}}</p><p>{{value}}</p></div></div><h3 class="font-semibold mt-6 mb-3">Chi tiết sản phẩm</h3><div v-for="detail in order.orderDetails || []" :key="detail.orderDetailId" class="p-3 mb-2 rounded bg-white/5">{{detail.productBatchCode || detail.productName || 'Sản phẩm'}} — {{detail.quantity}} × {{detail.unitPrice}}</div></div></section></template><script setup>import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{adminApi}from'../../api/adminService';const route=useRoute(),order=ref(null),error=ref('');const fields=computed(()=>({orderId:order.value.orderId,farmName:order.value.farmName,retailerName:order.value.retailerName,totalAmount:order.value.totalAmount,status:order.value.status,createdAt:order.value.createdAt}));onMounted(async()=>{try{order.value=(await adminApi.orders()).data.find(item=>String(item.orderId)===route.params.id);if(!order.value)error.value='Không tìm thấy đơn hàng.'}catch(e){error.value='Không thể tải đơn hàng.'}})</script>
